    const DType* __restrict__ q_input,
    const DType* __restrict__ weight,
    float weight_scale,
    const float* __restrict__ freqs,
    const PosT* __restrict__ positions,
    uint8_t* __restrict__ q_fp8,
    float* __restrict__ weights_out,
    uint32_t batch_size,
    uint32_t num_heads) {
  const uint32_t lane = threadIdx.x & (kWarpThreads - 1);
  const uint32_t warp = threadIdx.x >> 5;
  const uint32_t work_id = blockIdx.x * kWarpsPerBlock + warp;
  const uint32_t total = batch_size * num_heads;
  if (work_id >= total) return;

  const uint32_t batch_id = work_id / num_heads;
  const uint32_t elem = lane * kVecSize;

  const DType* in = q_input + static_cast<size_t>(work_id) * kHeadDim + elem;
  float data0 = to_float<DType>(in[0]);
  float data1 = to_float<DType>(in[1]);
  float data2 = to_float<DType>(in[2]);
  float data3 = to_float<DType>(in[3]);

  // RoPE on the last 64 dimensions.  Lanes 16..31 each hold two complex pairs.
  if (lane >= kWarpThreads - kRopeLanes) {
    const int pos = static_cast<int>(positions[batch_id]);
    const float* f = freqs + static_cast<size_t>(pos) * kRopeDim + (lane - (kWarpThreads - kRopeLanes)) * kVecSize;
    const float fxr = f[0], fxi = f[1], fyr = f[2], fyi = f[3];
    const float x_real = data0, x_imag = data1, y_real = data2, y_imag = data3;
    data0 = x_real * fxr - x_imag * fxi;
    data1 = x_real * fxi + x_imag * fxr;
    data2 = y_real * fyr - y_imag * fyi;
    data3 = y_real * fyi + y_imag * fyr;
  }

  // 128-point Hadamard in SGLang's lane-major order: two in-lane 4-point stages
  // followed by five warp-xor stages over the 32 lanes.
  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a1;
    data1 = a0 - a1;
    data2 = a2 + a3;
    data3 = a2 - a3;
  }
  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a2;
    data1 = a1 + a3;
    data2 = a0 - a2;
    data3 = a1 - a3;
  }
#pragma unroll
  for (uint32_t mask = 1; mask < kWarpThreads; mask <<= 1) {
    const float o0 = __shfl_xor_sync(0xffffffffu, data0, mask, kWarpThreads);
    const float o1 = __shfl_xor_sync(0xffffffffu, data1, mask, kWarpThreads);
    const float o2 = __shfl_xor_sync(0xffffffffu, data2, mask, kWarpThreads);
    const float o3 = __shfl_xor_sync(0xffffffffu, data3, mask, kWarpThreads);
    if (lane & mask) {
      data0 = o0 - data0;
      data1 = o1 - data1;
      data2 = o2 - data2;
      data3 = o3 - data3;
    } else {
      data0 += o0;
      data1 += o1;
      data2 += o2;
      data3 += o3;
    }
  }
  constexpr float had_scale = 0.08838834764831845f;  // rsqrt(128)
  data0 *= had_scale;
  data1 *= had_scale;
  data2 *= had_scale;
  data3 *= had_scale;

  float local_max = fmaxf(fmaxf(fabsf(data0), fabsf(data1)), fmaxf(fabsf(data2), fabsf(data3)));
#pragma unroll
  for (uint32_t mask = 16; mask > 0; mask >>= 1) {
    local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffffu, local_max, mask, kWarpThreads));
  }
  const float scale = fmaxf(1.0e-4f, local_max) / kFP8E4M3Max;
  const float inv_scale = 1.0f / scale;

  const uint16_t p01 = pack2_fp8(data0 * inv_scale, data1 * inv_scale);
  const uint16_t p23 = pack2_fp8(data2 * inv_scale, data3 * inv_scale);
  const uint32_t packed = static_cast<uint32_t>(p01) | (static_cast<uint32_t>(p23) << 16);
  reinterpret_cast<uint32_t*>(q_fp8 + static_cast<size_t>(work_id) * kHeadDim)[lane] = packed;

  // SGLang's reference path redundantly has all lanes store the same value.
  // Only lane 0 does it here, reducing one scalar load and 31 stores per row.
  if (lane == 0) {
    weights_out[work_id] = to_float<DType>(weight[work_id]) * weight_scale * scale;
  }
}

template <typename DType, typename PosT>
void launch_indexer(at::Tensor q_input, at::Tensor weight, double weight_scale,
                    at::Tensor freqs, at::Tensor positions, at::Tensor q_fp8,
                    at::Tensor weights_out) {
  const auto B = static_cast<uint32_t>(q_input.size(0));
  const auto H = static_cast<uint32_t>(q_input.size(1));
  if (B == 0 || H == 0) return;
  const uint32_t total = B * H;
  const dim3 grid((total + kWarpsPerBlock - 1) / kWarpsPerBlock);
  const dim3 block(kBlockThreads);
  auto stream = at::cuda::getCurrentCUDAStream();
  indexer_kernel<DType, PosT><<<grid, block, 0, stream>>>(
      reinterpret_cast<const DType*>(q_input.data_ptr()),
      reinterpret_cast<const DType*>(weight.data_ptr()),
      static_cast<float>(weight_scale),
      freqs.data_ptr<float>(),
      reinterpret_cast<const PosT*>(positions.data_ptr()),
      reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
      weights_out.data_ptr<float>(),
      B, H);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace

std::vector<at::Tensor> indexer_cuda(at::Tensor q_input, at::Tensor weight, double weight_scale,
                                     at::Tensor freqs, at::Tensor positions) {
  auto q_fp8 = at::empty(q_input.sizes(), q_input.options().dtype(at::kFloat8_e4m3fn));
  auto weights_out = at::empty({q_input.size(0), q_input.size(1), 1}, q_input.options().dtype(at::kFloat));

  if (q_input.scalar_type() == at::kHalf) {
    if (positions.scalar_type() == at::kInt) {
      launch_indexer<__half, int32_t>(q_input, weight, weight_scale, freqs, positions, q_fp8, weights_out);
    } else {
      launch_indexer<__half, int64_t>(q_input, weight, weight_scale, freqs, positions, q_fp8, weights_out);
    }
  } else {  // bfloat16
    if (positions.scalar_type() == at::kInt) {
      launch_indexer<__nv_bfloat16, int32_t>(q_input, weight, weight_scale, freqs, positions, q_fp8, weights_out);
    } else {
      launch_indexer<__nv_bfloat16, int64_t>(q_input, weight, weight_scale, freqs, positions, q_fp8, weights_out);
    }
  }
  return {q_fp8, weights_out};
}
