  const float inv_scale = 1.0f / scale;

  const uint16_t p01 = pack2_fp8(data0 * inv_scale, data1 * inv_scale);
  const uint16_t p23 = pack2_fp8(data2 * inv_scale, data3 * inv_scale);
  const uint32_t packed = static_cast<uint32_t>(p01) | (static_cast<uint32_t>(p23) << 16);
  reinterpret_cast<uint32_t*>(q_fp8 + static_cast<size_t>(work_id) * kHeadDim)[lane] = packed;

  // SGLang's reference path redundantly has all lanes store the same value.
  // Only lane 0 does it here, reducing one scalar load and 31 stores per row.
  if (lane == 0) {
    weights_out[work_id] = to_float<DType>(weight[work_id]) * weight_scale * scale;
  }
}

