    __nv_fp8x2_e4m3 v;
    uint16_t u;
  } out;
  out.v = __nv_fp8x2_e4m3(float2{clip_fp8(x), clip_fp8(y)});
  return out.u;
}

template <typename T>
__device__ __forceinline__ float to_float(T x);

template <>
__device__ __forceinline__ float to_float<__half>(__half x) {
  return __half2float(x);
}

