  float local_max = fmaxf(fmaxf(fabsf(data0), fabsf(data1)), fmaxf(fabsf(data2), fabsf(data3)));
#pragma unroll
  for (uint32_t mask = 16; mask > 0; mask >>= 1) {
    local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffffu, local_max, mask, kWarpThreads));
  }
  const float scale = fmaxf(1.0e-4f, local_max) / kFP8E4M3Max;
  const float inv_scale = 1.0f / scale;

  const uint16_t p01 = pack2_fp8(data0 * inv_scale, data1 * inv_scale);
  const uint16_t p23 = pack2_fp8(data2 * inv_scale, data3 * inv_scale);
  const uint32_t packed = static_cast<uint32_t>(p01) | (static_cast<uint32_t>(p23) << 16);
  reinterpret_cast<uint32_t*>(q_fp8 + static_cast<size_t>(work_id) * kHeadDim)[lane] = packed;

  // SGLang's reference path redundantly has all lanes store the same value.
  // Only lane 0 does it here, reducing one scalar load and 31 stores per row.
  if (lane == 0) {
    weights_out[work_id] = to_float<DType>(weight[work_id]) * weight_scale * scale;
  }
}

template <typename DType, typename PosT>
void launch_indexer(at::Tensor q_input, at::Tensor weight, double weight_scale,
                    at::Tensor freqs, at::Tensor positions, at::Tensor q_fp8,
                    at::Tensor weights_out) {
  const auto B = static_cast<uint32_t>(q_input.size(0));
  const auto H = static_cast<uint32_t>(q_input.size(1));
  if (B == 0 || H == 0) return;
  const uint32_t total = B * H;
  const dim3 grid((total + kWarpsPerBlock - 1) / kWarpsPerBlock);
  const dim3 block(kBlockThreads);
  auto stream = at::cuda::getCurrentCUDAStream();
  indexer_kernel<DType, PosT><<<grid, block, 0, stream>>>(
      reinterpret_cast<const DType*>(q_input.data_ptr()),
      reinterpret_cast<const DType*>(weight.data_ptr()),
      static_cast<float>(weight_scale),
      freqs.data_ptr<float>(),
      reinterpret_cast<const PosT*>(positions.data_ptr()),
      reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
      weights_out.data_ptr<float>(),
      B, H);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
}

}  // namespace


cudaError_t dsv4_indexer_launch(int dtype_code, bool pos_i64,
                                const void* q_input, const void* weight, float weight_scale,
                                const float* freqs, const void* positions,
                                void* q_fp8, float* weights_out,
                                uint32_t B, uint32_t H,
                                cudaStream_t stream) {
  const uint32_t total = B * H;
  const dim3 grid((total + kWarpsPerBlock - 1) / kWarpsPerBlock);
  const dim3 block(kBlockThreads);
  if (dtype_code == 0) {
    if (pos_i64) {
      indexer_kernel<__half, int64_t><<<grid, block, 0, stream>>>(
          static_cast<const __half*>(q_input), static_cast<const __half*>(weight), weight_scale,
          freqs, static_cast<const int64_t*>(positions), static_cast<uint8_t*>(q_fp8), weights_out, B, H);
    } else {
      indexer_kernel<__half, int32_t><<<grid, block, 0, stream>>>(
          static_cast<const __half*>(q_input), static_cast<const __half*>(weight), weight_scale,
          freqs, static_cast<const int32_t*>(positions), static_cast<uint8_t*>(q_fp8), weights_out, B, H);
    }
  } else {
    if (pos_i64) {
      indexer_kernel<__nv_bfloat16, int64_t><<<grid, block, 0, stream>>>(
          static_cast<const __nv_bfloat16*>(q_input), static_cast<const __nv_bfloat16*>(weight), weight_scale,
          freqs, static_cast<const int64_t*>(positions), static_cast<uint8_t*>(q_fp8), weights_out, B, H);
    } else {
      indexer_kernel<__nv_bfloat16, int32_t><<<grid, block, 0, stream>>>(
          static_cast<const __nv_bfloat16*>(q_input), static_cast<const __nv_bfloat16*>(weight), weight_scale,
          freqs, static_cast<const int32_t*>(positions), static_cast<uint8_t*>(q_fp8), weights_out, B, H);
    }
  }
  return cudaGetLastError();
